print('qpos',d.qpos)
for n in ['gripper','handle','mocap_target']:
 try:
  x=m.site(n).id; print('site',n,x,d.site_xpos[x],d.site_xmat[x].reshape(3,3))
 except Exception as e:
  try: print('body',n,d.xpos[m.body(n).id])
  except: print(e)
for i in range(m.nbody): print('body',i,m.body(i).name,'pos',d.xpos[i], 'mocap',m.body_mocapid[i])
print('joint names', [mujoco.mj_id2name(m,mujoco.mjtObj.mjOBJ_JOINT,i) for i in range(m.njnt)])
print('nq nv',m.nq,m.nv,'actrange',m.actuator_ctrlrange)
